    async def link_issue(
        self,
        task_id: str,
        *,
        issue_id: str,
        operation: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> LinkTaskIssueResponseBody:
        """
        Links the issue to the task by default. To unlink it, set the operation field to "unlink".

        **Rate limit:** 120 requests per minute

        Parameters
        ----------
        task_id : str
            The ID of the task to link a Pylon issue to.

        issue_id : str
            The ID of the Pylon issue.

        operation : typing.Optional[str]
            Operation to perform. Use "link" to link the issue (default) or "unlink" to unlink it.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        LinkTaskIssueResponseBody


        Examples
        --------
        import asyncio

        from usepylon import AsyncPylon

        client = AsyncPylon(
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.tasks.link_issue(
                task_id="id",
                issue_id="issue_id",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.link_issue(
            task_id, issue_id=issue_id, operation=operation, request_options=request_options
        )
        return _response.data

    @property
    def comments(self):
        if self._comments is None:
            from .comments.client import AsyncCommentsClient  # noqa: E402

            self._comments = AsyncCommentsClient(client_wrapper=self._client_wrapper)
